sys_script.script:
if (current.start_date && current.end_date) {
  var start = new GlideDateTime(current.start_date);
  var end = new GlideDateTime(current.end_date);
  var diff = end.getNumericValue() - start.getNumericValue();

  // 毫秒转小时
  var hours = Math.round(diff / (1000 * 60 * 60) * 100) / 100;
  current.leave_hours = hours;
}
